// Assess Grounding -- n8n Code node (Run Once for Each Item).
//
// The gate for Workflow 4. Decides, deterministically, whether this lead has
// enough real facts to write a grounded draft -- and if it does, builds the fact
// sheet and the prompts. No model call happens before this node has said yes.
//
// Section 9, Workflow 4, GROUNDING GUARD -- LOCKED:
//
//   "The drafting prompt may only use facts present in the enrichment record.
//    If the record lacks at least two specific facts (therapeutic area, named
//    trial, city, founder name), the draft is flagged `low-context` and skipped
//    rather than invented."
//
// The four categories in that sentence are the whole fact vocabulary. Nothing
// else counts toward the threshold -- deliberately, and two exclusions are worth
// naming because both are tempting:
//
//   country            -- every lead has one, and the pipeline only ingests the
//                        13 target geographies. Section 9's own reweight found
//                        geography "measures did our scraper touch this lead",
//                        not fit. A fact every lead shares grounds nothing.
//   site_quality_notes -- model-generated prose about a website. It reads like a
//                        fact and is the single highest fabrication risk field
//                        in the record. Using it to authorise a draft would let
//                        one model's invention license another's.
//
// Drafting skill v3 (NovaScout_DraftingSkill.md) leaves all of that untouched.
// What changed is what the model is given and asked for. v2 had a 9B model
// write a subject and two hooks and pasted claims-library lines in after them,
// verbatim. v3 sends the whole composition to Claude Sonnet 5.5: one prospect
// fact to open on, plus the approved claims for this lead -- descriptions, pain
// angles, benefits, the proof line matched to its country, the asks -- and the
// model writes the email around them. It may rephrase a claim, never widen it
// (skill section 0, rule 2); Assemble Drafts enforces section 3 on what comes
// back. The guard above still decides WHETHER a lead is drafted, before any
// API call is made.
//
// Master Ref build rule 3: this is all string matching, so it costs no tokens.

// ---------------------------------------------------------------------------
// Locked constants. build_workflow.py parses these out of NovaScout_MasterRef.md
// and refuses to generate the workflow if this file has drifted. An n8n Code
// node cannot import a shared module, which is the only reason these copies
// exist. When the doc changes, update these -- never the reverse.
// ---------------------------------------------------------------------------

// Section 9, Workflow 4: "If the record lacks at least two specific facts".
const MIN_FACTS = 2;

// Section 9, Workflow 3, "Therapeutic area taxonomy". A therapeutic area only
// counts as a grounding fact if it canonicalises against this locked list.
//
// This matters more here than it did in scoring. The live store is mixed: rows
// written before the enum was enforced hold free text, and some of that free
// text is not a therapeutic area at all ('pharma', 'medtech', 'fmcg',
// 'consumer health products'). Those are industry vocabulary, not a specialty.
// Letting one through would put "your work in FMCG" in front of a CRO founder,
// grounded in nothing but an extraction bug. Matching against the locked enum
// makes the guard behave identically on old and new rows.
const THERAPEUTIC_AREAS = [
  'Oncology',
  'Cardiovascular',
  'Central Nervous System',
  'Immunology',
  'Infectious Disease',
  'Endocrinology',
  'Metabolic Disorders',
  'Respiratory',
  'Rare Diseases',
  'Internal Medicine',
  'Anesthesiology',
  'Dermatology',
  'Rheumatology',
  'Ophthalmology',
  'Gastroenterology',
  'Nephrology',
  'Hematology',
  'Other',
];

// 'Other' is in the taxonomy but is by definition not a specific fact -- it is
// the catch-all. Grounding a draft in "your work in Other" is the failure this
// whole node exists to prevent.
const UNSPECIFIC_AREAS = ['Other'];

const AREA_BY_KEY = {};
for (const a of THERAPEUTIC_AREAS) AREA_BY_KEY[a.toLowerCase()] = a;

// Section 12: "Company: 5-100 employees." A headcount is not one of the four
// grounding facts and never counts toward MIN_FACTS. It is used for one thing
// only: the subject line, when no openable fact is available -- the skill's
// "small confirmed employee count" row. Enrichment records a number only when
// the site states one (code_fetch.js: "Never estimate"), so a non-null value in
// this band is the "confirmed" in that row.
const SMALL_TEAM = { min: 5, max: 100 };

// The claims-library slots a v3 email is composed from (NovaScout_DraftingSkill.md
// v3, section 4). A lead needs at least one active line in each, or it waits.
// `link` is optional and only ever used after warm-up, appended by code.
const LIBRARY_SLOTS = ['description', 'angle', 'benefit', 'proof', 'ask'];

// A role inbox is not a person -- Section 9, Workflow 3b, LOCKED:
//
//   "Where enrichment also named a founder the name, title and LinkedIn URL are
//    written alongside -- but the name is never presented as the owner of that
//    inbox, because no source says it is."
//
// So the email greeting is gated on the ADDRESS, not on whether a name is known.
// KLIXAR is the live case: Enrique Gaubeca is a confirmed founder with a
// confirmed LinkedIn profile, and hello@klixar.com is still not his mailbox.
// He gets greeted by name on LinkedIn and not by name over email.
const ROLE_LOCALPARTS = [
  'info', 'contact', 'contacts', 'hello', 'hi', 'connect', 'sales', 'admin',
  'office', 'enquiry', 'enquiries', 'inquiry', 'inquiries', 'mail', 'email',
  'support', 'help', 'team', 'general', 'reception', 'secretariat', 'marketing',
  'bd', 'business', 'businessdevelopment', 'careers', 'jobs', 'hr', 'press',
  'media', 'noreply', 'no-reply', 'donotreply', 'welcome', 'clinical',
  'research', 'cro', 'operations', 'ops', 'quality', 'regulatory',
];

// The drafting system prompt, substituted at build time by build_workflow.py
// (which is where it lives, next to the doc-parsed rules that shape it).
//
// It is emitted on every item rather than read from the Config node, because a
// Postgres node replaces the items entirely: anything Config set is gone by the
// time the batch query has run. Workflow 3 hit this first and solved it the same
// way -- code_score.js builds its own system_prompt and carries it forward.
const SYSTEM_PROMPT = "You write one cold first-touch email and one LinkedIn DM to a small contract\nresearch organisation (CRO), sent by Abdullah Amir. A person reviews both before\nanything is sent.\n\nEach message gives you two lists. VERIFIED FACTS are the only facts about the\nprospect that exist. APPROVED CLAIMS are the only things you may say about what we\nbuilt, the problem it solves, and who uses it. You may rephrase a claim. You may\nnever widen what it means.\n\nTHE PROSPECT -- one sentence, one fact.\n- Open each message from the fact you are told to open it with: exactly one\n  prospect fact, stated, about them (\"Your site lists ...\", \"Your recruiting\n  trial ...\").\n- Never build a sentence out of two facts. If fact 2 gives you a trial and fact 3\n  a city, \"your trial in that city\" is a claim neither fact makes. Each fact ends\n  with a sentence saying what it does not establish. Obey it literally.\n- Everything not in the facts does not exist: no headcount, no clients, no growth,\n  no plans, no praise of their website, no trial you were not given.\n- Never describe them as sponsoring anything. In these emails \"sponsor\" means the\n  biotech, pharma, device or academic company that hires a CRO -- their client.\n  Say \"running\", \"recruiting\" or \"your trial\".\n- A trial is on ClinicalTrials.gov, not on their site: never write \"your site\n  lists\" about a trial. Name one trial at most. Their site is where the\n  therapeutic areas come from, and a list of areas is what they work in, not a\n  list of trials.\n- Never open on a person's name or a city. Never write the company's name.\n\nTHE EMAIL, in about this order:\n  1. Hook -- the one prospect fact.\n  2. Pain and stakes -- ONE angle from the approved list. Do not stack them.\n  3. What it does -- a description from the list the first time you mention it,\n     then one or two benefits. Not more.\n     NO REPEATS: the description and the benefits must not repeat the same\n     capability. Each line says what it is about; never use two lines that share\n     one, and never restate in your own words what the description already said.\n  4. Proof -- the proof line you were given, matched to their country.\n  5. Ask -- exactly one, answerable with one word. It goes in the ask field; the\n     body before it asks for nothing.\n\nLENGTH: the body plus the ask is 70-110 words and never more than 125. Shorter is\nfine if nothing useful is lost. Say one thing well.\n\nSUBJECT: 30-55 characters, sentence case, no capitals except a name the facts\nspell that way. Build it from the fact the email opens with, or from the pain\nwhen you are told to. Never the product name. Never \"AI\". No \"Re:\", no \"Fwd:\".\n\nNAMING THE PRODUCT:\n- Describe it first, using a description line. The name appears at most once, in\n  brackets: \"(we call it Nova)\". Never \"Nova\" anywhere else.\n- Never call it a chatbot or a Q&A bot. It qualifies the inquiry, captures the\n  details, and passes the lead on.\n- The word \"AI\" appears at most once, inside the description. Never \"AI-powered\".\n\nCLAIMS -- forbidden, all of them:\n- guarantees (\"you'll never lose a sponsor\")\n- any number, percentage or multiplier that is not in the approved claims or the\n  facts\n- claiming to identify anonymous website visitors\n- naming any CRM, tool or integration\n- supported languages\n- any count of clients beyond the two named deployments\n- saying it books calls or fills a calendar -- it sends the sponsor your booking\n  link, and the sponsor books\n- saying it answers from SOPs or from documents -- it answers from their website\nThe stakes line is about the industry, not about us: \"a single sponsor inquiry\ncan be a multi-million-dollar study\" is allowed; \"we will win you millions\" is not.\n\nTHE ASK: one question. No links, no scheduling link, no call length, no second\nquestion.\n\nEVERYWHERE: plain text. No links of any kind, no bullets, no placeholders, no\nmerge tags. No greeting and no sign-off -- both are added afterwards. Never these\nwords: revolutionary, cutting-edge, innovative, game-changing, seamless. No invented urgency, no flattery, no\nexclamation marks.\n\nTHE LINKEDIN DM follows the same rules. It has no subject and may be shorter.\n\nOne example, for another company. Copy the shape and the restraint, never its\nfacts -- your facts are only the ones in your own numbered list.\n  Subject: Oncology sponsor inquiries after hours\n  Your site lists oncology and immunology. In those areas, a single sponsor inquiry can be a multi-million-dollar study, and sponsors often write outside your working hours, so that inquiry waits until morning while they contact the next CRO.\n\n  We built an AI assistant for CRO websites that answers sponsors from your own service pages at any hour, collects their therapeutic area and study phase, and sends qualified sponsors your booking link (we call it Nova). It's live at NoblePath, an oncology CRO in Türkiye.\n\n  Would a 48-hour demo built on your own material be worth a look? One word back is enough.\n\nReturn JSON: email_subject; email_body (everything before the ask, paragraphs\nseparated by a blank line); email_ask; linkedin_body; linkedin_ask; email_claims and\nlinkedin_claims (the code of every approved claim each message used).";

// The fixed part of the Anthropic Messages API request -- model, max_tokens,
// effort and the JSON schema -- substituted at build time by build_workflow.py,
// which parses the model id out of the skill and the Master Ref. Each item adds
// its own system prompt and user message; the HTTP node sends $json.request as
// the body. Building the body here rather than in an n8n expression keeps it
// testable, and keeps a `}}` in the schema from ending the expression early.
const CLAUDE_REQUEST = {
    "model": "claude-sonnet-5-5",
    "max_tokens": 16000,
    "output_config": {
      "effort": "high",
      "format": {
        "type": "json_schema",
        "schema": {
          "type": "object",
          "properties": {
            "email_subject": {
              "type": "string"
            },
            "email_body": {
              "type": "string"
            },
            "email_ask": {
              "type": "string"
            },
            "linkedin_body": {
              "type": "string"
            },
            "linkedin_ask": {
              "type": "string"
            },
            "email_claims": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "linkedin_claims": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          },
          "required": [
            "email_subject",
            "email_body",
            "email_ask",
            "linkedin_body",
            "linkedin_ask",
            "email_claims",
            "linkedin_claims"
          ],
          "additionalProperties": false
        }
      }
    }
  };

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// Diacritic-insensitive lowercase. 'Janos Biro' -> 'janos biro', so a local-part
// match against a name still works on the ASCII form a mail system would use.
// normalize('NFD') is one of the few Unicode helpers the n8n Code sandbox
// actually provides (verified against the live instance during Workflow 2).
function fold(v) {
  return str(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function canonicalAreas(raw) {
  const kept = [];
  const list = Array.isArray(raw) ? raw : [];
  for (const v of list) {
    if (v === null || v === undefined) continue;
    const canon = AREA_BY_KEY[String(v).trim().toLowerCase()];
    if (canon && UNSPECIFIC_AREAS.indexOf(canon) === -1 && kept.indexOf(canon) === -1) {
      kept.push(canon);
    }
  }
  return kept;
}

function localPart(email) {
  const e = str(email).toLowerCase();
  const at = e.indexOf('@');
  return at > 0 ? e.slice(0, at) : '';
}

// Does this address look like it belongs to the person we have a name for?
// Requires an actual token overlap -- 'devesh.kumar@' with no known name is NOT
// addressable by name, because we do not know that it is Devesh Kumar's; we
// only know the string. No source names the owner, so no greeting names them.
function addressIsPersons(email, name) {
  const lp = fold(localPart(email)).replace(/[^a-z]+/g, ' ').trim();
  if (!lp) return false;
  const nameTokens = fold(name).split(/[^a-z]+/).filter(function (t) { return t.length >= 3; });
  if (!nameTokens.length) return false;
  const lpTokens = lp.split(/\s+/).filter(Boolean);
  for (const nt of nameTokens) {
    if (lpTokens.indexOf(nt) !== -1) return true;
  }
  return false;
}

function isRoleInbox(email) {
  const lp = localPart(email);
  if (!lp) return false;
  const bare = lp.replace(/[^a-z0-9]+/g, '');
  return ROLE_LOCALPARTS.indexOf(lp) !== -1 || ROLE_LOCALPARTS.indexOf(bare) !== -1;
}

function firstName(name) {
  const parts = str(name).split(/\s+/).filter(Boolean);
  return parts.length ? parts[0] : '';
}

// The active claims-library rows, as the batch query aggregated them. A row
// with no text is not a line, whatever its flags say.
function libraryRows(raw) {
  const list = Array.isArray(raw) ? raw : [];
  const out = [];
  for (const r of list) {
    if (!r || typeof r !== 'object' || !str(r.body)) continue;
    out.push({
      code: str(r.code),
      slot: str(r.slot),
      body: str(r.body),
      countries: Array.isArray(r.countries) && r.countries.length ? r.countries.map(fold) : null,
      measured: r.measured === true,
      confirmed: r.confirmed === true,
      capabilities: Array.isArray(r.capabilities) ? r.capabilities.map(str).filter(Boolean) : [],
    });
  }
  return out;
}

// Which proof (or link) lines serve this lead. Skill section 3: "Geography-
// matched: Vertex Clinical Research for Mexico and Latin America; NoblePath for
// Turkiye and nearby; either elsewhere." The mapping itself is data -- each
// row's `countries` -- so the operator owns it. A row with no countries is the
// "elsewhere" line, used only when no row names the lead's country.
//
// Within the chosen rows a measured line wins: skill section 4, "When filled, it
// replaces the plain line above and becomes the strongest sentence in the email."
function forCountry(rows, country) {
  const key = fold(country);
  const serving = rows.filter(function (r) { return r.countries && r.countries.indexOf(key) !== -1; });
  const pick = serving.length ? serving : rows.filter(function (r) { return !r.countries; });
  const measured = pick.filter(function (r) { return r.measured; });
  return measured.length ? measured : pick;
}

function lines(rows) {
  return rows.map(function (r) {
    return { code: r.code, body: r.body, confirmed: r.confirmed, capabilities: r.capabilities };
  });
}

// Skill v3 section 3, No repeats: the description and the benefits must not
// repeat the same capability. Every pair of offered description/benefit lines
// that share one, worked out here so the prompt can name them outright rather
// than leave the model to compare capability lists. Assemble Drafts tags a
// message that uses one anyway (`claim-repeat`).
function repeatPairs(pool) {
  const pairs = [];
  for (let i = 0; i < pool.length; i++) {
    for (let j = i + 1; j < pool.length; j++) {
      const shared = (pool[i].capabilities || []).filter(function (c) {
        return (pool[j].capabilities || []).indexOf(c) !== -1;
      });
      if (shared.length) pairs.push({ a: pool[i].code, b: pool[j].code, shared: shared });
    }
  }
  return pairs;
}

// What a trial is called in a subject line. A title does not fit in 50
// characters, and left to shorten it the model pasted the whole title or -- worse
// -- borrowed "INM004" from the worked example for a trial that has no code at
// all. Both measured on Innovate Research. Picking the name is deterministic
// (build rule 3): the drug/study code if the title has one, otherwise its first
// two words that are not trial boilerplate.
const TITLE_FILLER = [
  'a', 'an', 'the', 'of', 'in', 'and', 'for', 'with', 'to', 'on', 'at', 'by', 'versus', 'vs',
  'study', 'trial', 'registry', 'efficacy', 'safety', 'evaluation', 'evaluating', 'effect',
  'effects', 'assessment', 'randomized', 'randomised', 'controlled', 'phase', 'open-label',
  'multicenter', 'multicentre', 'single', 'double', 'blind', 'double-blind', 'pilot',
  'clinical', 'prospective', 'observational', 'comparative', 'comparing', 'investigate',
];

function trialShortName(title) {
  const t = str(title);
  const code = t.match(/\b[A-Z]{1,6}-?\d{2,6}[A-Z]?\b/);
  if (code) return code[0];
  const content = t.split(/\s+/).filter(function (w) {
    return TITLE_FILLER.indexOf(w.toLowerCase().replace(/[^a-z-]/g, '')) === -1;
  });
  return content.slice(0, 2).join(' ').replace(/[,;:.]+$/, '');
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const lead = $('Get Draft Batch').item.json;
const ct = $input.item.json;

const base = {
  lead_id: lead.lead_id,
  domain: lead.domain,
  company_name: lead.company_name,
  country: lead.country,
  fit_score: lead.fit_score,
};

// --- Did ClinicalTrials.gov answer? ----------------------------------------
//
// Same self-healing shape as Workflow 3's "Drop Failed Lookups". If the lookup
// failed we do NOT quietly draft with one fewer fact -- that would let an API
// outage flip leads into low-context and permanently mark them as unwritable.
// The lead is dropped and stays 'contact_found' for the next run.
//
// JSON.stringify, not String(): n8n wraps an HTTP failure as an object and
// String() renders that '[object Object]', discarding the one field an operator
// needs. Same handling as code_score.js and code_pick_contact.js.
if (!ct || typeof ct !== 'object' || ct.error || typeof ct.totalCount !== 'number') {
  const err = ct && (ct.error || ct.message);
  const detail = err
    ? (typeof err === 'string' ? err : JSON.stringify(err)).slice(0, 300)
    : 'no numeric totalCount in the response';
  return {
    json: Object.assign({}, base, {
      ok: false,
      skip_reason: 'ClinicalTrials.gov lookup did not answer: ' + detail,
    }),
  };
}

// --- Collect the four locked fact categories -------------------------------

const areas = canonicalAreas(lead.therapeutic_areas);
const city = str(lead.city);
const founderName = str(lead.founder_name);
const founderTitle = str(lead.founder_title);

// Section 9's sponsor lookup is the only ClinicalTrials.gov query this project
// trusts. query.locn and query.term were both measured and rejected on false
// positives; a query.spons hit really is this company's trial, so its titles
// are safe to hand a drafting model.
const studies = Array.isArray(ct.studies) ? ct.studies : [];
const trialTitles = studies
  .map(function (s) {
    const p = s && s.protocolSection;
    const idm = p && p.identificationModule;
    return idm ? str(idm.briefTitle) : '';
  })
  .filter(Boolean)
  .slice(0, 3);
const trialCount = ct.totalCount;

// Each fact carries its own boundary -- what it does NOT establish -- in the
// same bullet as the fact itself.
//
// This is not decoration. Measured against real leads during the build, a sheet
// of bare attributes ("City: Istanbul", "Therapeutic areas: Oncology, ...")
// reliably produced sentences that JOINED two facts into a claim neither one
// makes: "one recruiting oncology trial in Istanbul", where the trial's area
// and location are both unknown. That is the Section 9 fabrication failure in
// its subtlest form -- every individual word traces to the record, and the
// sentence is still not true.
//
// Lowering the temperature did not fix it (tested at 0.35 and 0.7, same joins).
// Moving the boundary from a distant prompt rule into the bullet did.
// At most two areas reach the prompt, and the cap is applied HERE rather than
// asked for in the prompt. "Name at most two therapeutic areas" was in the
// instructions and the model listed five anyway ("You work in oncology,
// cardiovascular, rare diseases, respiratory, infectious disease" -- a database
// row, not a sentence). A model cannot list a fifth area it was never given.
// Build rule 3: this is deterministic, so it does not belong in a prompt.
//
// Oncology goes first when present -- Section 12 makes it the strongest signal
// and the NoblePath case study matches it. The rest keep taxonomy order, so the
// choice is stable across redrafts rather than depending on extraction order.
const promptAreas = areas.slice().sort(function (a, b) {
  if (a === 'Oncology') return -1;
  if (b === 'Oncology') return 1;
  return THERAPEUTIC_AREAS.indexOf(a) - THERAPEUTIC_AREAS.indexOf(b);
}).slice(0, 2);

const facts = [];
if (areas.length) {
  facts.push({
    kind: 'therapeutic_area',
    line:
      'Therapeutic areas listed on their own website: ' + promptAreas.join(' and ') +
      '. This says nothing about which area any particular trial belongs to.',
  });
}
if (trialCount > 0 && trialTitles.length) {
  facts.push({
    kind: 'named_trial',
    line:
      // Second person -- the model copies this line closely, so a third-person
      // phrasing came back as "this company" in a message addressed to that
      // company. But never "with you as the sponsor": skill v3 bans describing
      // the prospect as sponsoring anything, because "sponsor" now means the
      // CRO's client in every claim, and v2's "You're sponsoring ..." hooks put
      // one word on two parties in the same email.
      'ClinicalTrials.gov lists ' + trialCount + ' recruiting trial' +
      (trialCount === 1 ? '' : 's') + ' registered under your company. ' +
      // Phrased off how many titles came back, not off the total: pageSize caps
      // the titles at 3, so "2 trials ... it is titled" was a real mismatch.
      (trialTitles.length === 1 ? 'The only one named is' : 'The ones named are') + ': "' +
      trialTitles.join('"; "') +
      '". Nothing else about them is known -- not their phase, their therapeutic ' +
      'area, nor where they run.',
  });
}
if (city) {
  facts.push({
    kind: 'city',
    line:
      'The company is based in ' + city +
      '. This says nothing about where any trial runs or where any staff sit.',
  });
}
if (founderName) {
  facts.push({
    kind: 'founder_name',
    line:
      'Named on their own site as founder or MD: ' + founderName +
      (founderTitle ? ' (' + founderTitle + ')' : '') +
      '. This says nothing about which trials or clients this person personally handles.',
  });
}

const factKinds = facts.map(function (f) { return f.kind; });
const missing = ['therapeutic_area', 'named_trial', 'city', 'founder_name']
  .filter(function (k) { return factKinds.indexOf(k) === -1; });
const groundable = facts.length >= MIN_FACTS;

// --- How each channel may address this lead --------------------------------

const email = str(lead.email);
const contactName = str(lead.contact_name);
const linkedinUrl = str(lead.linkedin_url);

let emailAddressing;
if (!email) {
  emailAddressing = 'unaddressed';
} else if (isRoleInbox(email)) {
  emailAddressing = 'role-inbox';
} else if (contactName && addressIsPersons(email, contactName)) {
  emailAddressing = 'named';
} else {
  // A personal-shaped address whose owner no source names. Real and reachable,
  // but not greetable -- 'Devesh.kumar@' is a string, not an attribution.
  emailAddressing = 'unnamed';
}

const linkedinAddressing = linkedinUrl && contactName ? 'named' : 'no-profile';

const emailGreeting = emailAddressing === 'named' ? 'Hi ' + firstName(contactName) + ',' : 'Hello,';
const linkedinGreeting =
  linkedinAddressing === 'named' ? 'Hi ' + firstName(contactName) + ',' : 'Hello,';

// --- Prompts ---------------------------------------------------------------

const factSheet = facts
  .map(function (f, i) { return String(i + 1) + '. ' + f.line; })
  .join('\n');

// Which fact each channel opens from.
//
// Facts are collected in a fixed order (therapeutic area, trial, city, founder),
// so always opening from the first would make every email in a batch start on
// the same kind of sentence -- a merge-tag tell of exactly the sort Section 9
// bans, produced without a merge tag. Rotating on lead_id spreads the openings
// across the batch while staying deterministic: the same lead redrafted after a
// re-queue opens the same way, so a redraft is comparable to what it replaced.
//
// The LinkedIn DM opens from the next fact along, which is the cheapest way to
// stop it restating the email's first sentence -- the failure both temperature
// settings produced when the instruction was only "do not reuse a sentence".
//
// founder_name is excluded from opening either channel. It is a grounding fact
// -- it is evidence we know who this company is -- but it is not something you
// can tell its owner. Measured: opening from it produced "Enrique Gaubeca is
// founder or MD on their site" as the first line of a DM addressed to Enrique
// Gaubeca. A fact can be true, load-bearing for the guard, and still absurd as
// a sentence.
// city is excluded for a different reason than founder_name: it is not absurd,
// it is just thin. "You are based in Istanbul" is a weak opening sentence, and
// measured across three real leads at two temperatures the model reliably
// upgraded it into "You run trials in Istanbul" -- which is precisely the join
// the city fact's own boundary sentence forbids. Given nothing worth saying, it
// invents something worth saying. Do not hand it that opening.
const OPENABLE = ['named_trial', 'therapeutic_area'];

function idxWhere(pred) {
  const out = [];
  for (let i = 0; i < facts.length; i++) {
    if (pred(facts[i])) out.push(i);
  }
  return out;
}

// Three tiers, not two. A lead the guard passed on {city, founder_name} alone
// has nothing in OPENABLE, and rotating over "whatever is left" put the founder
// fact back in the opening slot -- the one outcome the exclusion above exists to
// prevent. So the fallback is ordered, not arbitrary: prefer a good opener, then
// anything that is not the founder, and only then give up.
const pool = (function () {
  const good = idxWhere(function (f) { return OPENABLE.indexOf(f.kind) !== -1; });
  if (good.length) return good;
  const notFounder = idxWhere(function (f) { return f.kind !== 'founder_name'; });
  if (notFounder.length) return notFounder;
  return facts.map(function (_, i) { return i; });
})();
const seed = Math.abs(parseInt(lead.lead_id, 10) || 0);
const openEmail = pool.length ? pool[seed % pool.length] : 0;
const openLinkedin = pool.length > 1
  ? pool[(seed + 1) % pool.length]
  : openEmail;

// --- What the subject line is built from -----------------------------------
//
// The same fact the email opens with, whenever that fact is one a subject can
// carry (a named trial, a therapeutic area). A subject about one fact over a
// hook about another reads as two emails stapled together -- and tying the two
// keeps the lead_id rotation above working for subjects as well, so two
// companies with the same fact shape do not get the same subject line.
//
// Only when the email opens from something a subject cannot use (the city
// fallback) does the ladder go further down: a small confirmed headcount, and
// failing that the pain itself, with no prospect fact at all. Skill v3: the
// subject is "built from a prospect fact or the pain".
const n = Number(lead.employee_estimate);
const headcount = lead.employee_estimate !== null && lead.employee_estimate !== undefined &&
  Number.isInteger(n) && n >= SMALL_TEAM.min && n <= SMALL_TEAM.max ? n : null;

const openEmailKind = facts.length ? facts[openEmail].kind : null;
let subjectSource;
if (openEmailKind === 'named_trial' || openEmailKind === 'therapeutic_area') {
  subjectSource = openEmailKind;
} else if (headcount !== null) {
  subjectSource = 'headcount';
} else {
  subjectSource = 'pain';
}

let subjectLines;
if (subjectSource === 'headcount') {
  subjectLines = [
    'Build the email subject from this headcount, and use it nowhere else -- not in',
    'either hook: their own site states a team of ' + headcount + ' people. This says',
    'nothing about what those people do or where they sit.',
  ];
} else if (subjectSource === 'pain') {
  subjectLines = [
    'None of these facts suits a subject line. Build the subject from the pain',
    'angle you chose instead, and put no fact about them in it.',
  ];
} else {
  subjectLines = [
    'Build the email subject from fact ' + (openEmail + 1) + ' too -- the same fact the email opens with.',
  ];
  if (subjectSource === 'named_trial' && trialTitles.length) {
    subjectLines.push('In the subject, call the trial "' + trialShortName(trialTitles[0]) + '".');
  }
}

// The trial fact reaches the model phrased from its source ("ClinicalTrials.gov
// lists ..."), and a model copies a fact line closely. Measured on the v2
// prompt: one hook in eight still opened "ClinicalTrials.gov lists ..." -- about
// the source, which the skill rules out. v2 fixed it by naming the opening
// words, "You're sponsoring"; skill v3 bans exactly that phrase, so the
// instruction now names v3's words instead. Assemble Drafts tags a hook that
// ignores either.
const trialOpeners = [openEmail, openLinkedin].some(function (i) {
  return facts.length && facts[i].kind === 'named_trial';
});

const prompt = [
  'Company: ' + str(lead.company_name),
  'Country: ' + str(lead.country),
  '',
  'VERIFIED FACTS. These are the only facts about this company that exist.',
  'Each one is numbered. Read the whole bullet, including the sentence saying',
  'what it does NOT establish:',
  factSheet,
  '',
  'Open the email from fact ' + (openEmail + 1) + '. Open the LinkedIn DM from fact ' +
    (openLinkedin + 1) + '.',
].concat(subjectLines, trialOpeners ? [
  'A hook built from the trial fact says "Your recruiting trial ..." or "You\'re',
  'running ..." -- about them, not about ClinicalTrials.gov, and never "sponsoring".',
] : []).join('\n');

// --- The approved claims library --------------------------------------------
//
// Everything in the email that is not a prospect fact comes from here (skill
// v3, section 0, rule 2): the model composes with these lines and may rephrase
// them, never widen them. They are resolved now, before any API money is
// spent: a groundable lead the library cannot complete -- no active line for a
// slot, or no proof line for its country and no fallback -- is dropped and
// stays 'contact_found' until the operator fixes the table. Same self-healing
// shape as a failed lookup: a gap in the operator's data must not mark a lead
// low-context, and it must not produce a draft with no proof in it.
//
// A lead that is not groundable does not need the library -- it gets the
// low-context note either way -- so it is not held back by it.
const lib = libraryRows(lead.library);
const bySlot = function (slot) { return lib.filter(function (r) { return r.slot === slot; }); };
const pools = {
  description: lines(bySlot('description')),
  angle: lines(bySlot('angle')),
  benefit: lines(bySlot('benefit')),
  proof: lines(forCountry(bySlot('proof'), lead.country)),
  ask: lines(bySlot('ask')),
};
const linkPool = lines(forCountry(bySlot('link'), lead.country));
const emptySlots = LIBRARY_SLOTS.filter(function (s) { return !pools[s].length; });
const libraryGap = emptySlots.length
  ? 'the claims library has no active ' + emptySlots.join(', ') + ' line' +
    (emptySlots.indexOf('proof') !== -1 ? ' (proof: none serves ' + str(lead.country) + ' and no fallback)' : '')
  : null;

// The claims, as the model sees them: each with its code, so it can report
// which each message used (Assemble Drafts checks every code against this list and
// records them in `variant` for the learning loop). Only this lead's proof line
// is offered -- the geography match is decided here, not by the model.
const CLAIM_HEADINGS = [
  ['description', 'DESCRIPTION -- introduce what we built with one of these, the first time you mention it:'],
  ['angle', 'PAIN AND STAKES ANGLES -- build the email around ONE:'],
  ['benefit', 'BENEFITS -- use one or two:'],
  ['proof', 'PROOF -- use this; it is matched to their country:'],
  ['ask', 'ASK -- end each message with ONE of these, rephrased if you like:'],
];
const claimsSheet = CLAIM_HEADINGS.map(function (h) {
  return [h[1]].concat(pools[h[0]].map(function (l) {
    const about = (h[0] === 'description' || h[0] === 'benefit') && l.capabilities.length
      ? '  (about: ' + l.capabilities.join(', ') + ')' : '';
    return '  [' + l.code + '] ' + l.body + about;
  })).join('\n');
}).join('\n\n');

const pairs = repeatPairs(pools.description.concat(pools.benefit));
const repeatSheet = pairs.length
  ? 'NO REPEATS -- the description and the benefits must not repeat the same capability. These\n' +
    'pairs say the same thing twice, so never use both lines of a pair in one message:\n' +
    pairs.map(function (p) { return '  ' + p.a + ' with ' + p.b + ' (both: ' + p.shared.join(', ') + ')'; }).join('\n') +
    '\n\n'
  : '';

const fullPrompt = prompt + '\n\nAPPROVED CLAIMS FOR THIS EMAIL. Nothing about the product, the problem or the\n' +
  'proof may come from anywhere else. Rephrase freely; never widen what a line says.\n\n' +
  claimsSheet + '\n\n' + repeatSheet +
  'Write the email subject, the email (body and ask) and the LinkedIn DM (body and ask).\n' +
  'Write no greeting and no sign-off -- those are added afterwards. In email_claims\n' +
  'and linkedin_claims, list the code of every claim that message used.';

// No cache_control on the system prompt. Measured on the 2026-10-02 run: the
// HTTP node dispatches every item's request before awaiting any, so a batch's
// calls run concurrently and none can read a cache another has not yet written
// (four calls, four cache writes, zero reads); and cron runs are 30 minutes
// apart, past the 5-minute cache lifetime. Caching only added the 25% write
// premium.
const request = Object.assign({}, CLAUDE_REQUEST, {
  system: SYSTEM_PROMPT,
  messages: [{ role: 'user', content: fullPrompt }],
});

// Warm-up week at draft time, from the same Sent-folder history the send path
// counts. NULL means no external send yet: the first send will be week 1.
const w = Number(lead.warmup_week);
const warmupWeek = Number.isInteger(w) && w >= 1 ? w : 1;

// Every taxonomy area this lead does NOT have. Assemble Drafts flags a draft
// naming one -- the worked example in the system prompt names oncology and
// immunology, and a model copies examples.
const absentAreas = THERAPEUTIC_AREAS.filter(function (a) {
  return UNSPECIFIC_AREAS.indexOf(a) === -1 && areas.indexOf(a) === -1;
});

const libraryHolds = groundable && libraryGap !== null;

return {
  json: Object.assign({}, base, {
    ok: !libraryHolds,
    skip_reason: libraryHolds ? libraryGap : undefined,
    groundable: groundable,
    fact_count: facts.length,
    fact_kinds: factKinds,
    missing_facts: missing,
    facts: facts,
    fact_sheet: factSheet,
    trial_count: trialCount,
    trial_titles: trialTitles,
    areas: areas,
    city: city,
    founder_name: founderName,
    contact_name: contactName,
    email: email,
    linkedin_url: linkedinUrl,
    email_addressing: emailAddressing,
    linkedin_addressing: linkedinAddressing,
    email_greeting: emailGreeting,
    linkedin_greeting: linkedinGreeting,
    open_email_fact: facts.length ? facts[openEmail].kind : null,
    open_linkedin_fact: facts.length ? facts[openLinkedin].kind : null,
    subject_source: subjectSource,
    headcount: headcount,
    absent_areas: absentAreas,
    library_pools: pools,
    repeat_pairs: pairs,
    library_link: linkPool,
    library_gap: libraryGap,
    warmup_week: warmupWeek,
    system_prompt: SYSTEM_PROMPT,
    prompt: fullPrompt,
    request: request,
  }),
};

// Assemble Drafts -- n8n Code node (Run Once for Each Item).
//
// Turns one Claude response into the two draft rows Section 9 asks for ("email
// variant + LinkedIn variant per lead into `drafts`"), and enforces every rule
// of NovaScout_DraftingSkill.md v3, section 3, that a string match can enforce.
//
// Skill v3 moved from verbatim line-picking to composition: Claude Sonnet 5.5
// writes the whole email -- subject, body and one ask -- from one prospect fact
// plus the approved claims Assess Grounding handed it. That makes this node the
// only thing standing between the model's prose and the review queue, so every
// rule the skill states as a rule is checked here, deterministically (build
// rule 3), on what actually came back:
//
//   length        body 70-110 words is the target; above 125 is tagged `long`
//   ask           exactly one: one question in the ask, no request in the body
//   links         none in warm-up weeks 1-2, then only the library's link line
//   product name  at most once, in brackets, never in the subject
//   "AI"          at most once, never in the subject, never "AI-powered"
//   sponsor       the prospect is never the one sponsoring ("You're sponsoring")
//   claims        no guarantee, no number the library and facts do not hold, no
//                 visitor identification, no named CRM or tool, no languages,
//                 never "chatbot", never that Nova books a call, never SOPs or
//                 client documents as its source; no two claim lines that
//                 repeat a capability
//   proof         the geography-matched deployment is named; no other one is
//   grounding     no therapeutic area the lead lacks; no founder or city opener;
//                 a trial is never credited to their website
//
// The opt-out sentence, the signature and the greeting are appended HERE, not
// generated. Section 5 locks the opt-out verbatim and makes it the whole basis
// for GDPR/KVKK legitimate interest.
//
// A violation tags the draft's `variant` rather than discarding it. The reviewer
// sees the tag next to the text; a silently dropped draft teaches nobody
// anything. Every draft still needs a human approval before Workflow 6 sends it.

// ---------------------------------------------------------------------------
// Locked constants. build_workflow.py parses each out of NovaScout_MasterRef.md
// or NovaScout_DraftingSkill.md and refuses to build on drift.
// ---------------------------------------------------------------------------

// Section 5, "Message rules -- LOCKED". Verbatim, including the straight
// apostrophes -- this string is the opt-out mechanism, not a paraphrase of it.
const OPT_OUT = "If this isn't relevant, reply 'no' and I won't follow up.";

// Skill v3 section 3, Length: "The body (everything above the opt-out line)
// should be 70-110 words and never more than 125." Counted over the body and
// the ask -- the greeting is the fixed frame, as in v2. Only the ceiling tags;
// "shorter is fine if nothing useful is lost".
const BODY_TARGET_MIN = 70;
const BODY_TARGET_MAX = 110;
const BODY_CEILING = 125;

// Section 5: "Maximum one plain URL. No buttons."
const MAX_URLS = 1;

// Master Ref Section 9, Workflow 4, Links: none in warm-up weeks 1-2. From week
// 3 the one URL Section 5 allows may appear -- and only the library's link
// line, appended here, never written by the model.
const LINK_FREE_WEEKS = 2;

// Skill v3 section 3, Subject: "30-55 characters ... Never the product name.
// Never 'AI'. No 'Re:', no 'Fwd:', no capitals."
const SUBJECT_MIN_CHARS = 30;
const SUBJECT_MAX_CHARS = 55;
const SUBJECT_REPLY_PREFIXES = ['re', 'fwd'];

// Skill v3 section 3, Naming the product: "The name appears at most once, in
// brackets". "The word 'AI' appears at most once".
const PRODUCT_NAME = 'Nova';
const PRODUCT_NAME_MAX = 1;
const AI_MAX = 1;

// Skill v3 section 3, Everywhere: "No banned adjectives (revolutionary,
// cutting-edge, innovative, game-changing, seamless)." The rest are the same
// register and fail the same way.
const BANNED_ADJECTIVES = [
  'revolutionary',
  'cutting-edge',
  'cutting edge',
  'innovative',
  'game-changing',
  'game changing',
  'seamless',
  'best-in-class',
  'world-class',
  'state-of-the-art',
  'leverage',
  'synergy',
  'unlock',
  'supercharge',
];

// The live deployments a proof line can name. Which of them this lead may hear
// about is decided by its proof pool (Assess Grounding, by country).
const DEPLOYMENTS = ['NoblePath', 'Vertex'];

// Skill v3 section 3, Claims, forbidden: "naming a specific CRM, tool or
// integration". Generic words ("your CRM", "a spreadsheet") are fine. Only
// names that are not also ordinary English words are listed, so a false
// positive costs a review tag, not a wrong one.
const NAMED_TOOLS = [
  'hubspot', 'salesforce', 'pipedrive', 'zoho', 'microsoft dynamics', 'dynamics 365', 'monday.com',
  'freshsales', 'freshworks', 'zendesk', 'google sheets', 'google sheet', 'airtable', 'slack',
  'microsoft teams', 'calendly', 'gmail', 'whatsapp', 'veeva', 'intercom', 'resend', 'mailchimp',
];

// Section 9, Workflow 4: "no merge-tag phrasing tells". The literal tags a
// template would leave behind ([First Name], {{company}}, <domain>).
const MERGE_TAG = /(\{\{[^}]*\}\})|(\[[A-Za-z][A-Za-z _-]{1,30}\])|(<[A-Za-z][A-Za-z _-]{1,30}>)/;

const URL_RE = /\b(?:https?:\/\/|www\.)[^\s<>()]+/gi;

// Skill v3 section 3, Hook: "Never describe the prospect as sponsoring anything
// ('You're sponsoring...' is banned)." Every way the v2 drafts and fact sheet
// put it.
const PROSPECT_SPONSOR = [
  /\byou(?:['’]re| are)\s+(?:also\s+|currently\s+|now\s+|actively\s+)?sponsor(?:ing|s)?\b/i,
  /\byou(?:['’]re| are)\s+(?:the|a|an)\s+(?:\w+\s+)?sponsor\b/i,
  /\byou\s+sponsor(?:ed|s)?\b/i,
  /\byou as (?:the |a )?sponsor\b/i,
  /\bsponsored by you\b/i,
  /\byour (?:own )?(?:sponsored|sponsorship)\b/i,
];

// Skill v3 section 3, Claims, forbidden. Each is a pattern for one rule.
const GUARANTEE = /\bguarantee\w*|\bnever (?:again )?(?:lose|miss)\b|\bno (?:lead|inquiry|inquiries|sponsor|sponsors) (?:is |are |gets |get |will be )?(?:ever )?(?:lost|missed)\b|\b100 ?%|\bwill (?:win|double|triple|increase|grow|boost)\b|\byou(?:['’]ll| will) (?:never|always|win|get more)\b|\b(?:ensures?|makes? sure) (?:you|that you) never\b/i;
const VISITOR_ID = /\b(?:identif\w*|reveal\w*|unmask\w*|de-?anonymi\w*|track\w*)\b[^.?!]{0,60}\b(?:visit\w*|visitors?|anonymous|traffic|browse\w*)\b|\banonymous (?:visitors?|traffic)\b|\b(?:see|know|tells? you|shows? you)\s+(?:exactly\s+)?(?:who|which \w+)\s+(?:visit\w*|browse\w*|land\w* on|came to)\b/i;
const LANGUAGES = /\bmulti-?lingual\b|\blanguages?\b|\b(?:turkish|spanish|arabic|german|french|portuguese|english|polish|romanian|hungarian|czech|hindi|urdu)\b/i;
const CHATBOT = /\bchat ?bots?\b|\bQ ?& ?A bots?\b/i;
const AI_POWERED = /\bAI[- ]?(?:powered|driven|based)\b/i;
// Settled 2026-10-02 against the Nova Agent Kit code (migration 013): Nova does
// not book -- it sends the booking link and the sponsor books through it -- and
// it answers from the CRO's website, never from SOPs or documents a client
// provides. "So they can book a call" is fine; Nova "books the call" is not.
const NOVA_BOOKS = /\bbooks\s+(?:the\s+|a\s+|qualified\s+|sponsor\s+)?(?:calls?|meetings?|demos?)\b|\b(?:into|onto|straight into)\s+your\s+(?:calendar|diary)\b|\bschedules\s+(?:the\s+|a\s+)?(?:calls?|meetings?)\b/i;
const SOP_SOURCE = /\bSOPs?\b|\bstandard operating procedures?\b|\b(?:your|their)\s+(?:own\s+)?(?:documents|documentation)\b/i;

// Skill v3 section 3, Claims: "any number, percentage or multiplier that is not
// in section 4". Digit tokens are checked against the library and the facts;
// these are the spelled-out numbers and multipliers a model reaches for. "one"
// is not here -- "one word back", "one question" are the skill's own words.
const NUMBER_WORDS = [
  'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'twenty',
  'thirty', 'fifty', 'hundred', 'hundreds', 'thousand', 'thousands', 'million', 'millions', 'billion',
  'dozen', 'dozens', 'double', 'doubles', 'doubled', 'triple', 'triples', 'tripled', 'twice', 'half',
  'percent', 'tenfold',
];
// A digit in the corpus licenses its word: the fact sheet says "2 recruiting
// trials", the model may write "two recruiting trials".
const DIGIT_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty'];

// Skill v3 section 3, Ask: "Exactly one ask. The reply costs one word. No
// links, no scheduling link, no '30-minute call'." The ask is its own field in
// the model's schema, so exactly one ask means: one question there, and no
// request anywhere in the body.
const REQUEST_IN_BODY = /\b(?:would you|could you|are you open|worth a (?:look|chat|call|try|conversation)|let me know|reply (?:yes|no|with|to)|one word back|shall i|should i|want me to|happy to (?:set|send|show|share|walk)|interested in (?:a|seeing|trying|hearing)|open to a|up for a|free for a)\b/i;
const ASK_SCHEDULING = /\b\d+[- ]?min(?:ute)?s?\b|\b(?:fifteen|twenty|thirty)[- ]minutes?\b|\bcalendly\b|\bschedul\w*|\bbook (?:a |some )?(?:time|slot|call|meeting)\b|\b(?:time|slot)s? (?:that )?works?\b/i;

// Skill v3 section 3, Hook: "Never open on the founder's name or the city."
// And the trial fact is on ClinicalTrials.gov, not on their site.
const HOOK_SOURCE_OPENING = /^\s*(clinicaltrials\.gov|according to)\b/i;
const SITE_CLAIM = /\b(your|their|the)\s+(web\s?)?site\b/i;
const TRIAL_WORD = /\b(trials?|stud(y|ies))\b/i;

// Acronyms a subject may carry in capitals.
const SUBJECT_ACRONYMS = ['CRO', 'CROS', 'BD'];

// The order claim codes are recorded in `variant`.
const SLOT_ORDER = ['description', 'angle', 'benefit', 'proof', 'ask', 'link'];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// A word is a token with a letter or a digit in it. A dash between clauses is
// punctuation, not a word.
function words(v) {
  const t = str(v);
  return t ? t.split(/\s+/).filter(function (w) { return /[\p{L}\p{N}]/u.test(w); }).length : 0;
}

function fold(v) {
  return str(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// A model that ignores "no greeting, no sign-off" produces a duplicate greeting
// once we prepend our own, and a sign-off that collides with the signature.
// Both are deterministic to strip.
const SIGNOFFS = [
  'best regards', 'kind regards', 'warm regards', 'best wishes', 'regards',
  'best', 'thanks', 'thank you', 'cheers', 'sincerely', 'yours sincerely',
];

function stripGreeting(body, greeting) {
  let out = str(body);
  const g = str(greeting).replace(/[,\s]+$/, '');
  // The trailing comma or colon is REQUIRED: optional, this ate the start of any
  // body that merely began with "Hi" or "Hello".
  out = out.replace(/^\s*(hi|hello|hey|dear|greetings)\b[^\n,]{0,40}[,:]\s*\n?/i, '');
  if (g && out.toLowerCase().indexOf(g.toLowerCase()) === 0) {
    out = out.slice(g.length).replace(/^[,\s]+/, '');
  }
  return out.trim();
}

function stripSignoff(body) {
  const lines = str(body).split('\n');
  while (lines.length) {
    const last = lines[lines.length - 1].trim().toLowerCase().replace(/[,.!]+$/, '');
    if (!last) { lines.pop(); continue; }
    if (SIGNOFFS.indexOf(last) !== -1 || (lines.length > 1 && /^[a-z]{2,20}$/.test(last))) {
      lines.pop();
      continue;
    }
    break;
  }
  return lines.join('\n').trim();
}

// Paragraphs as the model wrote them, blank-line separated, inner whitespace
// tidied; never more than one blank line in a row.
function cleanText(raw, greeting) {
  return stripSignoff(stripGreeting(raw, greeting))
    .split(/\n\s*\n/)
    .map(function (p) { return p.replace(/\s*\n\s*/g, ' ').trim(); })
    .filter(Boolean)
    .join('\n\n');
}

function urlsIn(v) {
  return str(v).match(URL_RE) || [];
}

function bannedAdjectivesIn(v) {
  const t = ' ' + str(v).toLowerCase() + ' ';
  return BANNED_ADJECTIVES.filter(function (a) { return t.indexOf(a) !== -1; });
}

// Trial titles are quoted from ClinicalTrials.gov and can hold anything -- a
// digit, a question mark, a therapeutic area. The checks judge what the model
// wrote around a title, not the title it was given.
function withoutTitles(text, titles) {
  let out = str(text);
  for (const t of titles || []) {
    const title = str(t);
    if (!title) continue;
    let at = out.toLowerCase().indexOf(title.toLowerCase());
    while (at !== -1) {
      out = out.slice(0, at) + ' ' + out.slice(at + title.length);
      at = out.toLowerCase().indexOf(title.toLowerCase());
    }
  }
  return out;
}

function digitTokens(v) {
  return (str(v).match(/[\p{L}\p{N}]*\p{N}[\p{L}\p{N}]*/gu) || []).map(function (t) { return t.toLowerCase(); });
}

// Numbers the text states that the corpus (this lead's facts plus every claim it
// was offered) does not: a digit token, a spelled-out number or multiplier, or a
// percent sign.
function unlicensedNumbers(text, corpus) {
  const haveDigits = {};
  digitTokens(corpus).forEach(function (t) { haveDigits[t] = true; });
  const bad = digitTokens(text).filter(function (t) { return !haveDigits[t]; });
  let corpusWords = ' ' + fold(corpus).replace(/[^a-z0-9]+/g, ' ') + ' ';
  Object.keys(haveDigits).forEach(function (t) {
    if (/^\d+$/.test(t) && Number(t) < DIGIT_WORDS.length) corpusWords += DIGIT_WORDS[Number(t)] + ' ';
  });
  const textWords = fold(text).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean);
  textWords.forEach(function (w) {
    if (NUMBER_WORDS.indexOf(w) !== -1 && corpusWords.indexOf(' ' + w + ' ') === -1) bad.push(w);
  });
  if (str(text).indexOf('%') !== -1 && str(corpus).indexOf('%') === -1) bad.push('%');
  return bad;
}

function absentAreasNamed(text, absentAreas) {
  const plain = ' ' + fold(text).replace(/[^a-z0-9]+/g, ' ') + ' ';
  return (absentAreas || []).filter(function (a) {
    return plain.indexOf(' ' + fold(a).replace(/[^a-z0-9]+/g, ' ') + ' ') !== -1;
  });
}

// Does the text open on this name (or its first word)? Plain string compare.
function startsWithName(text, name) {
  const t = fold(text);
  const n = fold(name);
  if (!n) return false;
  const first = n.split(/\s+/)[0];
  const opensOn = function (w) {
    return t.indexOf(w) === 0 && (t.length === w.length || !/[a-z0-9]/.test(t.charAt(w.length)));
  };
  return opensOn(n) || (first.length >= 3 && opensOn(first));
}

function firstSentence(text) {
  const m = str(text).match(/^[\s\S]*?[.!?](?=\s|$)/);
  return m ? m[0] : str(text);
}

function countOf(re, text) {
  return (str(text).match(new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags)) || []).length;
}

// ---------------------------------------------------------------------------
// The rule checks. Each returns the tags it found; checkMessage runs them all.
// ---------------------------------------------------------------------------

// "Exactly one ask."
function askFlags(body, ask) {
  const flags = [];
  const q = countOf(/\?/, ask);
  if (!str(ask) || q === 0) flags.push('ask-none');
  if (q > 1 || REQUEST_IN_BODY.test(body)) flags.push('ask-multiple');
  if (ASK_SCHEDULING.test(ask)) flags.push('ask-scheduling');
  return flags;
}

// "The name appears at most once, in brackets." Stripping every bracketed
// segment leaves nothing that may still say the name.
function productFlags(text) {
  const flags = [];
  const name = new RegExp('\\b' + PRODUCT_NAME + '\\b', 'gi');
  const n = countOf(name, text);
  if (n > PRODUCT_NAME_MAX) flags.push('product-name-repeat');
  const unbracketed = str(text).replace(/\([^()]*\)/g, ' ');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(unbracketed)) flags.push('product-name-unbracketed');
  return flags;
}

// "The word 'AI' appears at most once ... Never 'AI-powered'."
function aiFlags(text) {
  const flags = [];
  if (countOf(/\bA\.?I\b\.?/, text) > AI_MAX) flags.push('ai-repeat');
  if (AI_POWERED.test(text)) flags.push('ai-powered');
  return flags;
}

function prospectSponsor(text) {
  return PROSPECT_SPONSOR.some(function (re) { return re.test(text); });
}

// Skill v3 section 3, Claims, forbidden.
function claimFlags(text, corpus) {
  const flags = [];
  if (GUARANTEE.test(text)) flags.push('claim-guarantee');
  if (unlicensedNumbers(text, corpus).length) flags.push('claim-number');
  if (VISITOR_ID.test(text)) flags.push('claim-visitor-id');
  const t = ' ' + fold(text) + ' ';
  if (NAMED_TOOLS.some(function (n) { return new RegExp('(^|[^a-z0-9])' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(t); })) {
    flags.push('claim-named-tool');
  }
  if (LANGUAGES.test(text)) flags.push('claim-language');
  if (CHATBOT.test(text)) flags.push('claim-chatbot');
  if (NOVA_BOOKS.test(text)) flags.push('claim-books');
  if (SOP_SOURCE.test(text)) flags.push('claim-sop');
  return flags;
}

// Skill v3 section 3, No repeats: "The description and the benefits must not
// repeat the same capability." Each description and benefit line names its
// capabilities (claims_library.capabilities, migration 013); two codes one
// message used that share one say the same thing twice. `capsOf(code)` returns
// a code's capabilities (none for an angle, proof or ask).
function repeatFlags(codes, capsOf) {
  const flags = [];
  const seen = {};
  let repeated = false;
  for (const code of codes || []) {
    for (const cap of capsOf(code) || []) {
      if (seen[cap] && seen[cap] !== code) repeated = true;
      seen[cap] = code;
    }
  }
  if (repeated) flags.push('claim-repeat');
  return flags;
}

// "Proof: one named live deployment, matched to the lead's geography."
function proofFlags(text, proofPool) {
  const flags = [];
  const pool = proofPool || [];
  const allowed = DEPLOYMENTS.filter(function (d) {
    return pool.some(function (p) { return fold(p.body).indexOf(fold(d)) !== -1; });
  });
  const both = pool.some(function (p) { return /\btwo CROs\b/i.test(p.body); });
  const named = DEPLOYMENTS.filter(function (d) { return fold(text).indexOf(fold(d)) !== -1; });
  if (named.some(function (d) { return allowed.indexOf(d) === -1; })) flags.push('proof-geo');
  const present = named.some(function (d) { return allowed.indexOf(d) !== -1; }) ||
    (both && /\btwo (?:CROs|CRO clients|clients)\b/i.test(text));
  if (!present) flags.push('proof-missing');
  return flags;
}

// The first sentence opens on the prospect fact. Section 9 Workflow 4:
// founder_name and city never open a message; a trial is never credited to
// their website.
function hookFlags(hook, src, titles) {
  const flags = [];
  if (startsWithName(hook, src.founder_name) || startsWithName(hook, src.city)) flags.push('hook-opener');
  const own = withoutTitles(hook, titles);
  const titlesNamed = (titles || []).filter(function (t) {
    return str(t) && hook.toLowerCase().indexOf(str(t).toLowerCase()) !== -1;
  }).length;
  const trialOnSite = SITE_CLAIM.test(own) && (titlesNamed > 0 || TRIAL_WORD.test(own));
  if (HOOK_SOURCE_OPENING.test(hook) || trialOnSite) flags.push('hook-source');
  return flags;
}

function linkFlags(text, week, approvedLink) {
  const flags = [];
  const urls = urlsIn(text);
  if (urls.length > MAX_URLS) flags.push('urls');
  if (urls.length && week <= LINK_FREE_WEEKS) flags.push('link-in-warmup');
  const approved = approvedLink ? urlsIn(approvedLink.body) : [];
  if (urls.some(function (u) { return approved.indexOf(u) === -1; })) flags.push('unapproved-link');
  if (urls.some(function (u) { return /linkedin\.com/i.test(u); })) flags.push('linkedin-link');
  if (urls.some(function (u) { return /\.pdf\b/i.test(u); })) flags.push('pdf-link');
  return flags;
}

function subjectFlags(subject, factCorpus, headcount, titles, absentAreas) {
  const flags = [];
  const chars = Array.from(subject).length;
  if (!subject || chars < SUBJECT_MIN_CHARS || chars > SUBJECT_MAX_CHARS) flags.push('subject');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(subject)) flags.push('subject-product');
  if (/\bA\.?I\b/i.test(subject)) flags.push('subject-ai');
  const prefix = new RegExp('\\b(' + SUBJECT_REPLY_PREFIXES.join('|') + ')\\s*:', 'i');
  if (prefix.test(subject)) flags.push('subject-reply');
  // "No capitals": sentence case. A capitalised word after the first is allowed
  // only when the facts spell it that way (a trial code, a city) or it is an
  // acronym a CRO uses.
  const corpusWords = {};
  (factCorpus.match(/[\p{L}\p{N}-]+/gu) || []).forEach(function (t) { corpusWords[t] = true; });
  const tokens = subject.match(/[\p{L}\p{N}-]+/gu) || [];
  const capped = tokens.filter(function (t, i) {
    if (!/\p{Lu}/u.test(t)) return false;
    if (i === 0 && !/^\p{Lu}{2,}$/u.test(t)) return false;
    return !corpusWords[t] && SUBJECT_ACRONYMS.indexOf(t.toUpperCase()) === -1;
  });
  if (capped.length) flags.push('subject-caps');
  const corpus = factCorpus + (headcount ? ' ' + headcount : '');
  const bare = withoutTitles(subject, titles);
  if (digitTokens(bare).some(function (t) { return digitTokens(corpus).indexOf(t) === -1; }) ||
      absentAreasNamed(bare, absentAreas).length) {
    flags.push('subject-ungrounded');
  }
  return flags;
}

// Every rule that applies to a message body, either channel.
function checkMessage(m) {
  let flags = [];
  if (!str(m.body)) flags.push('empty');
  if (words(m.core) > BODY_CEILING) flags.push('long');
  if (bannedAdjectivesIn(m.core).length) flags.push('adjective');
  if (MERGE_TAG.test(m.core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(m.body, m.ask));
  flags = flags.concat(productFlags(m.core));
  flags = flags.concat(aiFlags(m.core));
  if (prospectSponsor(m.core)) flags.push('prospect-sponsor');
  const own = withoutTitles(m.core, m.titles);
  flags = flags.concat(claimFlags(own, m.corpus));
  if (absentAreasNamed(own, m.absentAreas).length) flags.push('ungrounded-area');
  if (str(m.body)) flags = flags.concat(hookFlags(firstSentence(m.body), m.src, m.titles));
  flags = flags.concat(proofFlags(m.core, m.proofPool));
  return flags;
}

function unique(list) {
  return list.filter(function (v, i) { return list.indexOf(v) === i; });
}

// Word-set overlap, for attributing an ask the model did not code to the library
// line it paraphrased. Also used by the follow-ups (Workflow 6), which embed
// everything above "Node body" verbatim.
function wordSet(v) {
  const set = {};
  fold(v).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean).forEach(function (w) { set[w] = true; });
  return set;
}
function jaccard(a, b) {
  const A = wordSet(a);
  const B = wordSet(b);
  const keys = unique(Object.keys(A).concat(Object.keys(B)));
  const both = keys.filter(function (k) { return A[k] && B[k]; }).length;
  return keys.length ? both / keys.length : 0;
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const src = $('Assess Grounding').item.json;
const resp = $input.item.json;

const base = {
  lead_id: src.lead_id,
  domain: src.domain,
  company_name: src.company_name,
  fit_score: src.fit_score,
};

// --- Did Claude answer, completely, with the schema we asked for? -----------
//
// The HTTP node continues on error, so a failed call arrives as a normal item.
// Skill v3 section 6: "If the API call fails, the lead stays queued and the
// next run retries. No fallback to the local model." So any failure -- an HTTP
// error, a refusal, a response cut off at max_tokens, text that is not the
// schema -- writes nothing, and the lead stays 'contact_found'.
function failed(detail) {
  return {
    json: Object.assign({}, base, {
      write: false,
      skip_reason: 'Claude drafting call did not answer usably: ' + detail,
      usage: resp && resp.usage ? resp.usage : null,
    }),
  };
}

if (!resp || typeof resp !== 'object') return failed('no response item');
if (resp.error) {
  const e = resp.error;
  return failed((typeof e === 'string' ? e : JSON.stringify(e)).slice(0, 300));
}
if (resp.stop_reason !== 'end_turn') {
  const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
  return failed('stop_reason ' + JSON.stringify(resp.stop_reason) + why);
}
const text = (Array.isArray(resp.content) ? resp.content : [])
  .filter(function (b) { return b && b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('');
let parsed = null;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}
const FIELDS = ['email_subject', 'email_body', 'email_ask', 'linkedin_body', 'linkedin_ask'];
const CLAIM_LISTS = ['email_claims', 'linkedin_claims'];
if (!parsed || typeof parsed !== 'object' ||
    FIELDS.some(function (f) { return typeof parsed[f] !== 'string'; }) ||
    CLAIM_LISTS.some(function (f) { return !Array.isArray(parsed[f]); })) {
  return failed('response text was not the drafting schema: ' + text.slice(0, 200));
}

// Section 5: the signature is name / one line of title / phone, appended
// verbatim; nothing is invented to fill a gap.
const SIGNATURE = "Abdullah Amir\nFounder, Amitrix Labs\n+923178485713";

const week = Number(src.warmup_week) || 1;
const pools = src.library_pools || {};

// --- Which claims the model says each message used --------------------------
//
// Reported per message, because `variant` is what the learning loop reads to
// see which claims earn replies: one list for both messages recorded the DM's
// ask against the email (measured on the first v3 run). Every code is checked
// against what this lead was offered; one that was not is tagged `claim-code`
// (and so is reporting none). The known codes, in slot order, go into that
// message's `variant`.
const offered = {};
SLOT_ORDER.forEach(function (slot) {
  (pools[slot] || []).forEach(function (l) {
    offered[l.code] = { slot: slot, confirmed: l.confirmed, capabilities: l.capabilities || [] };
  });
});
// The ask and the proof are also attributed in code, from the text, when the
// model leaves their code out. Measured on the 2026-10-02 run: three of eight
// messages ended on an approved ask -- one of them word for word -- and listed
// no ask code, so `variant` lost the one slot the learning loop most needs.
// Same rule as enrichment: never rely on a model to copy an identifier; name
// the thing, then match it deterministically. The ask is the library line whose
// words it shares most (at least half, by Jaccard on word sets); the proof is
// the line whose deployment it names, or PR-BOTH's "two CROs".
function inferAsk(askText) {
  let best = null;
  (pools.ask || []).forEach(function (l) {
    const j = jaccard(askText, l.body);
    if (j >= 0.5 && (!best || j > best.j)) best = { code: l.code, j: j };
  });
  return best ? best.code : null;
}
function inferProof(core) {
  const hit = (pools.proof || []).filter(function (l) {
    const names = DEPLOYMENTS.filter(function (d) { return fold(l.body).indexOf(fold(d)) !== -1; });
    return names.length ? names.some(function (d) { return fold(core).indexOf(fold(d)) !== -1; })
      : (/\btwo CROs\b/i.test(l.body) && /\btwo (?:CROs|CRO clients|clients)\b/i.test(core));
  });
  return hit.length ? hit[0].code : null;
}
function claimsOf(list, askText, core) {
  const reported = unique(list.map(str).filter(Boolean));
  const used = reported.filter(function (c) { return offered[c]; });
  const hasSlot = function (slot) { return used.some(function (c) { return offered[c].slot === slot; }); };
  const inferred = [];
  if (!hasSlot('ask')) { const a = inferAsk(askText); if (a) inferred.push(a); }
  if (!hasSlot('proof')) { const p = inferProof(core); if (p) inferred.push(p); }
  return {
    reported: reported,
    inferred: inferred,
    unknown: reported.filter(function (c) { return !offered[c]; }),
    used: used.concat(inferred).sort(function (a, b) {
      return SLOT_ORDER.indexOf(offered[a].slot) - SLOT_ORDER.indexOf(offered[b].slot);
    }),
  };
}

// Existing link policy: none in warm-up weeks 1-2; after that, at most the
// library's link line, appended by code. The LinkedIn DM never carries it -- a
// human sends that from their own profile (Section 6).
const linkLines = week > LINK_FREE_WEEKS ? (src.library_link || []) : [];
const link = linkLines.length ? linkLines[Math.abs(parseInt(src.lead_id, 10) || 0) % linkLines.length] : null;

// --- Compose the sendable text ----------------------------------------------

const emailSubject = str(parsed.email_subject).replace(/\s+/g, ' ');
const emailBody = cleanText(parsed.email_body, src.email_greeting);
const emailAsk = cleanText(parsed.email_ask, src.email_greeting);
const linkedinBody = cleanText(parsed.linkedin_body, src.linkedin_greeting);
const linkedinAsk = cleanText(parsed.linkedin_ask, src.linkedin_greeting);

// The body the length rule counts: everything between the greeting and the
// opt-out line.
const emailCore = [emailBody].concat(link ? [link.body] : [], [emailAsk]).filter(Boolean).join('\n\n');
const linkedinCore = [linkedinBody, linkedinAsk].filter(Boolean).join('\n\n');

// Email: greeting / body / ask / opt-out / signature. The opt-out-then-
// signature tail is exactly what Workflow 6 checks for before it will send.
const emailMessage = [src.email_greeting, '', emailCore, '', OPT_OUT].join('\n');
const emailFull = SIGNATURE ? emailMessage + '\n\n' + SIGNATURE : emailMessage;

// LinkedIn: greeting / body / ask. No opt-out sentence and no signature --
// Section 6 makes this a DM a human reads and sends from their own account.
const linkedinFull = [src.linkedin_greeting, '', linkedinCore].join('\n');

const emailClaims = claimsOf(parsed.email_claims, emailAsk, emailCore);
const linkedinClaims = claimsOf(parsed.linkedin_claims, linkedinAsk, linkedinCore);

// --- Deterministic constraint checks ----------------------------------------

const titles = src.trial_titles || [];
const factCorpus = str(src.fact_sheet);
const claimCorpus = SLOT_ORDER.map(function (slot) {
  return (pools[slot] || []).map(function (l) { return l.body; }).join('\n');
}).join('\n');
// The fact sheet's own numbering ("1. ...", "2. ...") is layout, not a fact: left
// in, it licensed "two" and "three" in every draft.
const corpus = factCorpus.replace(/^\d+\.\s/gm, '') + '\n' + claimCorpus + (link ? '\n' + link.body : '');

function message(body, ask, core) {
  return {
    body: body, ask: ask, core: core, titles: titles, corpus: corpus, src: src,
    absentAreas: src.absent_areas, proofPool: pools.proof,
  };
}

function claimTags(claims, withLink) {
  let flags = [];
  if (claims.unknown.length || !claims.reported.length) flags.push('claim-code');
  flags = flags.concat(repeatFlags(claims.used, function (c) { return offered[c].capabilities; }));
  const anyUnconfirmed = claims.used.some(function (c) { return !offered[c].confirmed; }) ||
    (withLink && !withLink.confirmed);
  if (anyUnconfirmed) flags.push('unconfirmed-claim');
  return flags;
}

function checkEmail() {
  let flags = checkMessage(message(emailBody, emailAsk, emailCore));
  flags = flags.concat(linkFlags(emailCore + '\n' + emailSubject, week, link));
  flags = flags.concat(subjectFlags(emailSubject, factCorpus, src.headcount, titles, src.absent_areas));
  if (prospectSponsor(emailSubject)) flags.push('prospect-sponsor');
  return unique(flags.concat(claimTags(emailClaims, link)));
}

// The DM is sent by a human from their own account (Section 6): no subject, and
// no link of any kind.
function checkLinkedin() {
  let flags = checkMessage(message(linkedinBody, linkedinAsk, linkedinCore));
  flags = flags.concat(linkFlags(linkedinCore, week, null));
  return unique(flags.concat(claimTags(linkedinClaims, null)));
}

// variant = addressing / claim codes used + flags.
function variantTag(addressing, codes, flags) {
  const v = addressing + '/' + codes;
  return flags.length ? v + '+' + flags.join(',') : v;
}

const codes = emailClaims.used.concat(link ? [link.code] : []).join('.');
const linkedinCodes = linkedinClaims.used.join('.');
const emailFlags = checkEmail();
const linkedinFlags = checkLinkedin();

return {
  json: Object.assign({}, base, {
    write: true,
    low_context: false,
    fact_count: src.fact_count,
    fact_kinds: src.fact_kinds,
    email_flags: emailFlags,
    linkedin_flags: linkedinFlags,
    email_words: words(emailCore),
    linkedin_words: words(linkedinCore),
    email_claims: emailClaims.used,
    linkedin_claims: linkedinClaims.used,
    unknown_claims: unique(emailClaims.unknown.concat(linkedinClaims.unknown)),
    model: resp.model,
    usage: resp.usage || null,
    payload: {
      lead_id: src.lead_id,
      advance: true,
      drafts: [
        {
          channel: 'email',
          variant: variantTag(src.email_addressing, codes, emailFlags),
          subject: emailSubject,
          body: emailFull,
        },
        {
          channel: 'linkedin',
          variant: variantTag(src.linkedin_addressing, linkedinCodes, linkedinFlags),
          subject: null,
          body: linkedinFull,
        },
      ],
    },
  }),
};

// Build Low-Context Drafts -- n8n Code node (Run Once for Each Item).
//
// The other side of the grounding guard. Section 9, Workflow 4:
//
//   "If the record lacks at least two specific facts ... the draft is flagged
//    `low-context` and skipped rather than invented."
//
// "Skipped" cannot mean "write nothing". A lead that produces no row stays at
// status='contact_found' and is re-picked, re-looked-up and re-skipped by every
// subsequent cron tick, forever. That is the same trap Workflow 3b's tombstone
// was built to avoid, and the answer is the same: record the outcome.
//
// So the lead does advance to 'drafted', and it does appear in the review
// queue -- carrying a row that says plainly what was missing instead of a
// paragraph a 9B model made up to fill the gap. Section 9's own "visibility
// over spot-checking" decision (taken for is_cro disqualifications) points the
// same way: surface the miss to the human, do not hide it.
//
// No model call happens on this branch. There is nothing to write from.

const src = $input.item.json;

const LABELS = {
  therapeutic_area: 'a therapeutic area from the locked taxonomy',
  named_trial: 'a recruiting trial registered with them as sponsor',
  city: 'a city',
  founder_name: 'a named founder or MD',
};

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

const have = (src.fact_kinds || []).map(function (k) { return LABELS[k] || k; });
const missing = (src.missing_facts || []).map(function (k) { return LABELS[k] || k; });

const note = [
  'NOT DRAFTED -- low context.',
  '',
  'The grounding guard (Master Ref Section 9, Workflow 4) requires at least two',
  'specific facts in the enrichment record before a draft may be written. This',
  'lead has ' + (have.length || 'none') + '.',
  '',
  'Found: ' + (have.length ? have.join('; ') : 'nothing usable'),
  'Missing: ' + (missing.length ? missing.join('; ') : 'nothing'),
  '',
  'Nothing was generated, deliberately -- a model given one fact invents the',
  'rest. To rescue this lead: re-enrich it, or write the outreach by hand from',
  'the company site. Reject it if it is not worth either.',
].join('\n');

return {
  json: Object.assign({}, {
    lead_id: src.lead_id,
    domain: src.domain,
    company_name: src.company_name,
    fit_score: src.fit_score,
  }, {
    write: true,
    low_context: true,
    fact_count: src.fact_count,
    fact_kinds: src.fact_kinds,
    missing_facts: src.missing_facts,
    payload: {
      lead_id: src.lead_id,
      advance: true,
      drafts: [
        {
          channel: 'email',
          // The addressing mode is still recorded. It is real information -- it
          // tells the reviewer whether a manual email has anywhere to go.
          variant: 'low-context/' + str(src.email_addressing),
          subject: null,
          body: note,
        },
        {
          channel: 'linkedin',
          variant: 'low-context/' + str(src.linkedin_addressing),
          subject: null,
          body: note,
        },
      ],
    },
  }),
};
